import{_ as s,o as n,c as o,ag as a}from"./chunks/framework.1IVNT0ce.js";const y=JSON.parse('{"title":"Input Engine","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/input-engine.md","filePath":"concepts/input-engine.md"}'),t={name:"concepts/input-engine.md"};function l(i,e,p,r,c,d){return n(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="input-engine" tabindex="-1">Input Engine <a class="header-anchor" href="#input-engine" aria-label="Permalink to &quot;Input Engine&quot;">​</a></h1><p>The input engine is Klix&#39;s thin wrapper around <code>prompt_toolkit</code>. It provides the prompt session, input modes, key bindings, and CI-safe fallback behavior.</p><p>See also:</p><ul><li><a href="./ui">UI Namespace</a></li><li><a href="./../guides/input-modes">Input Modes</a></li><li><a href="./../components/input">Input Components</a></li></ul><h2 id="why-it-exists" tabindex="-1">Why It Exists <a class="header-anchor" href="#why-it-exists" aria-label="Permalink to &quot;Why It Exists&quot;">​</a></h2><p>Klix needs one place to own terminal input behavior so that:</p><ul><li>prompt history is consistent</li><li>key bindings are centralized</li><li>modes can influence prompt behavior</li><li>CI and pipe mode can bypass interactive UI cleanly</li></ul><p>Without that layer, every input component would need to reinvent prompt setup.</p><h2 id="what-the-engine-handles" tabindex="-1">What The Engine Handles <a class="header-anchor" href="#what-the-engine-handles" aria-label="Permalink to &quot;What The Engine Handles&quot;">​</a></h2><p>Current responsibilities:</p><ul><li><code>PromptSession</code> setup</li><li>session-backed command history</li><li>current <code>InputMode</code></li><li><code>Ctrl+L</code> binding</li><li>multiline bindings</li><li>password mode flagging</li><li>optional clear-after-submit behavior</li><li>optional themed prompt styling</li><li>CI/non-TTY fallback via <code>stdin.readline()</code></li></ul><h2 id="ci-and-non-interactive-behavior" tabindex="-1">CI And Non-Interactive Behavior <a class="header-anchor" href="#ci-and-non-interactive-behavior" aria-label="Permalink to &quot;CI And Non-Interactive Behavior&quot;">​</a></h2><p>When Klix selects <code>CIRenderer</code>, the input engine avoids interactive prompt_toolkit use and reads lines from stdin instead.</p><p>That is why tests can do things like:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#82AAFF;">printf</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">/hello hi\\n/exit\\n</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;"> |</span><span style="color:#FFCB6B;"> python</span><span style="color:#C3E88D;"> main.py</span></span></code></pre></div><p>This is great for automation, but it also means some richer widgets are effectively interactive-only. See <a href="./../components/input">Input Components</a>.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p>The engine currently understands:</p><ul><li><code>COMMAND</code></li><li><code>MULTILINE</code></li><li><code>SELECT</code></li><li><code>SEARCH</code></li><li><code>CONFIRM</code></li><li><code>PASSWORD</code></li><li><code>INTERRUPT</code></li></ul><p>In the current implementation, not every mode changes low-level prompt behavior equally. Some modes are primarily semantic signals used by higher-level components.</p><p>Examples:</p><ul><li><code>PASSWORD</code> changes prompt masking</li><li><code>MULTILINE</code> changes Enter behavior</li><li><code>COMMAND</code> mode participates in session history navigation</li><li>selector-style inputs are implemented through prompt_toolkit dialogs in <code>session.ui.input</code>, not directly through <code>prompt_async()</code></li></ul><h2 id="realistic-example" tabindex="-1">Realistic Example <a class="header-anchor" href="#realistic-example" aria-label="Permalink to &quot;Realistic Example&quot;">​</a></h2><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/notes</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Capture a multiline note</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> def</span><span style="color:#82AAFF;"> notes</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">):</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set_mode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">InputMode</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">MULTILINE</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">    text </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">prompt_async</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Note &gt; </span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set_mode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">InputMode</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">COMMAND</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">output</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">panel</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">text</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> title</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Captured Note</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> border_color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">accent</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><h2 id="key-bindings" tabindex="-1">Key Bindings <a class="header-anchor" href="#key-bindings" aria-label="Permalink to &quot;Key Bindings&quot;">​</a></h2><p>Current built-ins:</p><ul><li><code>Ctrl+L</code> clears the screen</li><li>Up/Down navigate session history through prompt_toolkit</li><li>in multiline mode: <ul><li><code>Escape</code> + <code>Enter</code> inserts a newline</li><li><code>Ctrl+J</code> inserts a newline in terminals that emit LF</li><li><code>Enter</code> submits</li></ul></li></ul><p>When <code>AppConfig(clear_input_on_submit=True)</code> is enabled, the active prompt line is also erased after submit.</p><p>If <code>ThemeConfig(input_background=...)</code> is set, prompt_toolkit applies a themed input bar background in interactive terminals.</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><h3 id="assuming-every-input-component-goes-through-prompt-async" tabindex="-1">Assuming every input component goes through <code>prompt_async()</code> <a class="header-anchor" href="#assuming-every-input-component-goes-through-prompt-async" aria-label="Permalink to &quot;Assuming every input component goes through \`prompt_async()\`&quot;">​</a></h3><p>Simple prompts do. Richer selectors often build their own prompt_toolkit sessions or dialogs on top of the same engine-level context.</p><h3 id="forgetting-to-reset-mode" tabindex="-1">Forgetting to reset mode <a class="header-anchor" href="#forgetting-to-reset-mode" aria-label="Permalink to &quot;Forgetting to reset mode&quot;">​</a></h3><p>If you manually change modes in custom flows, return to <code>COMMAND</code> when you are done.</p><h3 id="expecting-rich-dialogs-in-ci" tabindex="-1">Expecting rich dialogs in CI <a class="header-anchor" href="#expecting-rich-dialogs-in-ci" aria-label="Permalink to &quot;Expecting rich dialogs in CI&quot;">​</a></h3><p>CI fallback is intentionally plain.</p>`,36)])])}const u=s(t,[["render",l]]);export{y as __pageData,u as default};
